/** Render only bundled, Python-derived SYNTHETIC v0.4 artifacts. No import API. */
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ref=value=>`${esc(value.document_kind||value.kind)} ${esc(value.identifier)}${value.version?' @ '+esc(value.version):''} · ${esc(value.instance)}/${esc(value.scope)}${value.repository?' · repository '+esc(value.repository):''}${value.provider?' · provider '+esc(value.provider):''}${value.context?' · context '+esc(value.context):''}${value.configuration?' · mapping '+esc(value.configuration):''}${value.algorithm?' · algorithm '+esc(value.algorithm):''}`;
const badge=value=>`<span class="trace-status">${esc(value)}</span>`;
export function renderVerification(report){
 if(report?.schema_version!=='v0.4-demo-1'||report.synthetic!==true)throw Error('Select a bundled synthetic v0.4 evidence scenario.');
 return `<h2>Requirements, tests and architecture evidence</h2><p>${badge('SYNTHETIC')} Collection ${badge(report.collection_status)} · Rule ${esc(report.rule_version)}</p><p class="privacy">${esc(report.warning)}</p>
 <h3>Coverage dimensions</h3><p class="muted">Counts describe independently observed retained populations. Unknown and excluded evidence are separate; no success rate or readiness score is computed.</p><div class="table-scroll"><table><thead><tr><th>Dimension</th><th>Qualified / selected</th><th>Fraction / status</th><th>Unknown / excluded</th><th>Reason</th></tr></thead><tbody>${report.metrics.map(m=>`<tr><td>${esc(m.dimension)}</td><td>${m.numerator} / ${m.denominator}</td><td>${m.value===null?'Unavailable':(m.value*100).toFixed(1)+'%'} · ${badge(m.status)}</td><td>${m.unknown_count} / ${m.excluded_count}</td><td>${esc(m.reason||'—')}</td></tr>`).join('')}</tbody></table></div>
 <h3>Qualified historical observation counts</h3><div class="risk-grid">${Object.entries(report.outcomes).map(([outcome,count])=>`<div><span>${esc(outcome)}</span><strong>${count}</strong></div>`).join('')}</div><p class="muted">PASS and FAIL both establish that a qualified execution observation exists. SKIPPED and UNKNOWN do not count as executed tests. Different runs may disagree.</p>
 <h3>Requirements</h3><div class="table-scroll"><table><thead><tr><th>Requirement / version</th><th>Implementation evidence</th><th>Declared test linkage</th><th>Architecture linkage</th></tr></thead><tbody>${report.requirements.map(r=>`<tr><td>${ref(r.reference)}</td><td>${badge(r.implementation)}</td><td>${badge(r.tests)}</td><td>${badge(r.architecture)}</td></tr>`).join('')}</tbody></table></div>${report.requirements.length?'':'<p class="empty">No independently selected requirements. Coverage is unavailable, not zero.</p>'}
 <h3>Explicit versioned associations</h3>${report.associations.map(a=>`<p>${ref(a.source)} → ${ref(a.target)}<br>${esc(a.relation)} · ${esc(a.origin)} · boundary ${esc(a.boundary)}</p>`).join('')||'<p class="empty">No retained explicit associations.</p>'}
 <h3>Requirement → code evidence</h3>${report.paths.map(p=>`<details class="trace-card"><summary>${ref(p.association.source)} → ${p.code_path.nodes.map(n=>ref(n)).join(' → ')} ${badge(p.code_path.status)}</summary><p>${esc(p.association.relation)} · ${esc(p.association.origin)} · boundary ${esc(p.association.boundary)}</p><ol>${p.code_path.supports.map(s=>`<li>${ref(s.source)} → ${ref(s.target)} · ${esc(s.type)} · ${esc(s.origin)}</li>`).join('')}</ol><p>Code boundaries: ${esc(p.code_path.boundaries.join(', '))} · code rule ${esc(p.code_path.rule_version)}</p><ul>${p.code_path.gaps.map(g=>`<li>${ref(g.endpoint)} · ${esc(g.relationship)} · ${esc(g.direction)} · ${badge(g.status)} · ${esc(g.reason)}</li>`).join('')}</ul></details>`).join('')||'<p class="empty">No retained requirement-code paths.</p>'}
 <h3>Declared verification observations</h3>${report.runs.map(r=>`<details class="trace-card"><summary>${ref(r.reference)} → ${ref(r.test)} ${badge(r.outcome)} · ${r.qualified?'Qualified target/version':'Excluded from qualified outcomes'}</summary><p>${esc(r.reason||'Exact test version and target snapshot/revision')} · ${esc(r.observed_at)} · boundary ${esc(r.boundary)} · group ${esc(r.group||'Not declared')}</p><p>Target ${esc(r.target.alias)} · ${esc(r.target.repository)} · revision ${esc(r.target.revision)} · fingerprint ${esc(r.target.fingerprint)}</p></details>`).join('')||'<p class="empty">No retained run observations. Conflicting identities are quarantined, not resolved to PASS.</p>'}
 <h3>Unresolved requirement segments</h3><ul>${report.gaps.map(g=>`<li>${ref(g.endpoint)} · ${esc(g.relation)} · ${esc(g.direction)} · ${badge(g.status)} · ${esc(g.reason)}</li>`).join('')}</ul>
 <h3>Collection diagnostics</h3><ul>${report.diagnostics.map(d=>`<li>${esc(d.reason)}${d.endpoint?' · '+ref(d.endpoint):''} · ${esc(d.relation||'Collection scope')}</li>`).join('')}</ul>
 <details class="trace-card"><summary>Snapshot, limits and lookup provenance</summary><p>Snapshot join: ${report.snapshot_valid?'Valid exact public snapshot':'Unavailable — snapshot mismatch'}</p><dl>${Object.entries(report.snapshot).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}<dt>Evidence boundary</dt><dd>${esc(report.boundary)} · ${esc(report.collected_at)}</dd></dl><p>Dropped at limits: ${Object.entries(report.dropped).map(([k,v])=>`${esc(k)} ${v}`).join(' · ')}</p><ul>${report.lookups.map(l=>`<li>${l.endpoint?ref(l.endpoint):esc(l.population)} · ${esc(l.relation||'POPULATION')} · ${esc(l.direction)} · ${badge(l.status)} · ${esc(l.capability)}</li>`).join('')}</ul></details>`;
}
